package org.apache.commons.lang3.text.translate;

import junit.framework.TestCase;
import java.io.StringWriter;
import java.nio.CharBuffer;

public class LookupTranslatorBugOriginTest extends TestCase {
    public void testLookupTranslatorWithCharBuffer() throws Exception {
        CharSequence cs2 = CharBuffer.wrap("1 < 2".toCharArray());

        // The constructor takes CharSequence[]... lookup
        LookupTranslator translator = new LookupTranslator(new CharSequence[][] {
            new CharSequence[] { "<", "&lt;" }
        });

        // translate(CharSequence input, int index, Writer out)
        // We need to iterate through the input to see if it translates.
        // Or we can try to translate at the specific index where "<" is.
        // "1 < 2" -> '<' is at index 2.

        StringWriter out = new StringWriter();
        int consumed = translator.translate(cs2, 2, out);

        // If it works, it should return 1 (length of "<") and write "&lt;" to out.
        // If it fails (bug), it should return 0 and write nothing.

        assertEquals("Should have consumed 1 character", 1, consumed);
        assertEquals("Should have translated to &lt;", "&lt;", out.toString());
    }
}

