package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringUtilsBugOriginTest extends TestCase {

    /**
     * A simple CharSequence that does not implement equals(Object) 
     * in a way that compares content with other CharSequence types.
     */
    private static class CustomCharSequence implements CharSequence {
        private final String data;

        public CustomCharSequence(String data) {
            this.data = data;
        }

        public int length() {
            return data.length();
        }

        public char charAt(int index) {
            return data.charAt(index);
        }

        public CharSequence subSequence(int start, int end) {
            return data.subSequence(start, end);
        }

        public String toString() {
            return data;
        }

        /**
         * Default equals(Object) from Object, which is identity comparison.
         */
        public boolean equals(Object obj) {
            return this == obj;
        }
    }

    public void testEqualsWithCustomCharSequence() {
        CharSequence cs1 = new CustomCharSequence("abc");
        CharSequence cs2 = new StringBuilder("abc");

        // StringUtils.equals(CharSequence, CharSequence) should return true 
        // if the characters are the same, regardless of the classes' equals() implementation.
        // The bug is that it returns false because it calls cs1.equals(cs2).
        assertTrue("StringUtils.equals(CharSequence, CharSequence) should compare content", 
                   StringUtils.equals(cs1, cs2));
    }
}

