import junit.framework.TestCase;

public class FractionBugOriginTest extends TestCase {
    public void testReduceZeroNumerator() {
        Fraction f = Fraction.getFraction(0, 1);
        // The report says there is an infinite loop in reduce() when numerator is 0.
        // We call reduce() and expect it to return (or not hang).
        // If it hangs, the test will timeout (or we can assert it returns a specific value if known).
        // According to LANG-380, reduce() on 0/x should probably return Fraction.ZERO.
        Fraction reduced = f.reduce();
        assertEquals(0, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }
