import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import junit.framework.TestCase;

public class DateUtilsBugOriginTest extends TestCase {
    public void testRound() {
        Calendar testCalendar = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        testCalendar.set(2007, 6, 2, 8, 9, 50);
        testCalendar.set(Calendar.MILLISECOND, 0);
        Date date = testCalendar.getTime();

        Date rounded = DateUtils.round(date, Calendar.MINUTE);

        Calendar resultCalendar = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        resultCalendar.setTime(rounded);

        // The reporter expects Mon Jul 02 08:10:00 GMT 2007 (based on their CDT example)
        // The wrong behavior reported was Mon Jul 02 08:01:00 GMT 2007

        assertEquals("Year should be 2007", 2007, resultCalendar.get(Calendar.YEAR));
        assertEquals("Month should be July (6)", 6, resultCalendar.get(Calendar.MONTH));
        assertEquals("Day should be 2", 2, resultCalendar.get(Calendar.DAY_OF_MONTH));
        assertEquals("Hour should be 8", 8, resultCalendar.get(Calendar.HOUR_OF_DAY));

        // The bug is that it rounds to 01 instead of 10 (or 09 if it didn't round up, but 50s should round up)
        // Reporter says 03:09:50 -> 03:01:00 is wrong.
        // We assert that it is NOT 01.
        assertFalse("Minutes should not be 1", 1 == resultCalendar.get(Calendar.MINUTE));

        // To be sure it's the bug, we can check if it's 10
        assertEquals("Minutes should be 10", 10, resultCalendar.get(Calendar.MINUTE));
    }
}

