package org.apache.commons.lang3.text;

import junit.framework.TestCase;

public class StrBuilderBugOriginTest extends TestCase {
    public void testLang295() {
        StrBuilder sb = new StrBuilder("abc");
        sb.minimizeCapacity();

        // The bug report says thisBuf.length is used instead of size.
        // minimizeCapacity() is one of the methods that might be affected.
        // If it uses thisBuf.length, it might not shrink correctly or might behave inconsistently.
        // However, the report is a bit vague on the exact failure.
        // Let's try to reproduce a situation where thisBuf.length != size.

        StrBuilder sb2 = new StrBuilder(10);
        sb2.append("abc");
        // size = 3, thisBuf.length = 10

        // If a method uses thisBuf.length instead of size, it might process 10 elements instead of 3.
        // Let's check indexOf or contains which are common candidates for such bugs.

        assertEquals("indexOf(String) should find the string", 0, sb2.indexOf("abc"));
        assertEquals("indexOf(String, int) should not find the string past its end", -1, sb2.indexOf("abc", 4));

        // Another candidate: delete(int, int) or replace(int, int, String)
        // But let's look at the methods that use thisBuf.length.
        // Based on the description "StrBuilder contains usages of thisBuf.length when they should use size",
        // let's try to find a method that behaves wrongly when capacity > size.

        StrBuilder sb3 = new StrBuilder(10);
        sb3.append("abc");
        // If contains(char) used thisBuf.length, it might find a null char if the buffer is padded with nulls.
        assertFalse("Should not contain null character", sb3.contains('\0'));
    }
}

